import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int rows = sc.nextInt();
        int cols = sc.nextInt();
        int[][] cost = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                cost[r][c] = sc.nextInt();
            }
        }
        int[][] best = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (r == 0 && c == 0) {
                    best[r][c] = cost[r][c];
                } else if (r == 0) {
                    best[r][c] = best[r][c - 1] + cost[r][c];
                } else if (c == 0) {
                    best[r][c] = best[r - 1][c] + cost[r][c];
                } else {
                    best[r][c] = Math.min(best[r - 1][c], best[r][c - 1]) + cost[r][c];
                }
            }
        }
        for (int[] row : best) {
            StringBuilder sb = new StringBuilder();
            for (int b : row) {
                sb.append(String.format("%3d", b));
            }
            System.out.println(sb);
        }
        System.out.println("Cheapest: " + best[rows - 1][cols - 1]);
    }
}
